-- VLUX Loyalty 1.0 · Verificación de SOLO LECTURA tras aplicar 0016 (catálogo; no lee datos de negocios). Todas las filas deben decir ok = true.
SELECT 'migración 0016 registrada con su checksum' AS comprobacion, EXISTS (SELECT 1 FROM schema_migrations WHERE version = '0016_tenant_isolation' AND checksum = 'b55d29db99d1fdbaa3b26534d86730d83d74b2df265adcbf409d006e31396459') AS ok
UNION ALL SELECT 'existe el rol vlux_app', EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'vlux_app')
UNION ALL SELECT 'las 9 tablas siguen con RLS activa', (SELECT count(*) = 9 FROM pg_class WHERE relnamespace = 'public'::regnamespace AND relname IN ('business_deletions','business_subscriptions','card_access_tokens','email_events','email_outbox','platform_audit_events','staff_invitations','staff_memberships','staff_sessions') AND relkind = 'r' AND relrowsecurity)
UNION ALL SELECT 'ninguna política USING (true) en las 9 tablas', NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('business_deletions','business_subscriptions','card_access_tokens','email_events','email_outbox','platform_audit_events','staff_invitations','staff_memberships','staff_sessions') AND (qual = 'true' OR policyname = 'app_only'))
UNION ALL SELECT 'la única política abierta es el INSERT de la bitácora', (SELECT count(*) = 1 FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('business_deletions','business_subscriptions','card_access_tokens','email_events','email_outbox','platform_audit_events','staff_invitations','staff_memberships','staff_sessions') AND with_check = 'true')
UNION ALL SELECT 'vlux_app sin superusuario ni BYPASSRLS', NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'vlux_app' AND (rolsuper OR rolbypassrls))
UNION ALL SELECT 'vlux_app sin UPDATE de tabla completa en las 6 tablas', NOT EXISTS (SELECT 1 FROM information_schema.table_privileges WHERE grantee = 'vlux_app' AND privilege_type = 'UPDATE' AND table_schema = 'public' AND table_name IN ('business_subscriptions','card_access_tokens','email_outbox','staff_invitations','staff_memberships','staff_sessions'))
UNION ALL SELECT 'UPDATE por columnas exactamente el de 0016 (6 tablas, 29 columnas)', (SELECT count(*) = 29 AND bool_and((table_name, column_name) IN (('business_subscriptions','plan_code'),('business_subscriptions','commercial_status'),('business_subscriptions','start_date'),('business_subscriptions','pilot_end_date'),('business_subscriptions','renewal_date'),('business_subscriptions','price_cents'),('business_subscriptions','currency'),('business_subscriptions','notes'),('business_subscriptions','updated_by'),('card_access_tokens','revoked_at'),('card_access_tokens','last_used_at'),('email_outbox','status'),('email_outbox','provider'),('email_outbox','provider_message_id'),('email_outbox','attempts'),('email_outbox','sends_accepted'),('email_outbox','last_error'),('email_outbox','requested_at'),('email_outbox','accepted_at'),('email_outbox','delivered_at'),('email_outbox','failed_at'),('email_outbox','link_enc'),('staff_invitations','accepted_at'),('staff_invitations','accepted_user_id'),('staff_invitations','revoked_at'),('staff_invitations','failed_attempts'),('staff_memberships','role'),('staff_memberships','active'),('staff_sessions','revoked_at'))) FROM information_schema.column_privileges WHERE grantee = 'vlux_app' AND privilege_type = 'UPDATE' AND table_schema = 'public' AND table_name IN ('business_subscriptions','card_access_tokens','email_outbox','staff_invitations','staff_memberships','staff_sessions'))
UNION ALL SELECT 'vlux_app sin DELETE en las 9 tablas', NOT EXISTS (SELECT 1 FROM information_schema.table_privileges WHERE grantee = 'vlux_app' AND privilege_type = 'DELETE' AND table_schema = 'public' AND table_name IN ('business_deletions','business_subscriptions','card_access_tokens','email_events','email_outbox','platform_audit_events','staff_invitations','staff_memberships','staff_sessions'))
UNION ALL SELECT 'vlux_app no ejecuta las funciones *_impl', NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname LIKE '%\_impl' AND has_function_privilege('vlux_app', p.oid, 'EXECUTE'))
UNION ALL SELECT 'vlux_app ejecuta las 5 envolturas y app_scope()', (SELECT count(*) = 6 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('platform_business_stats','platform_recent_activity','platform_business_export','platform_purge_business','notification_due_businesses','app_scope') AND has_function_privilege('vlux_app', p.oid, 'EXECUTE'))
UNION ALL SELECT 'ninguna función de public ejecutable por PUBLIC/anon/authenticated', NOT EXISTS (SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) a LEFT JOIN pg_roles r ON r.oid = a.grantee WHERE p.pronamespace = 'public'::regnamespace AND a.privilege_type = 'EXECUTE' AND (a.grantee = 0 OR r.rolname IN ('anon','authenticated')))
UNION ALL SELECT 'las envolturas SECURITY DEFINER tienen search_path fijo', NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prosecdef AND NOT COALESCE(p.proconfig::text LIKE '%search_path=%', false));
